package lc130

import "testing"

func construct(compact []string) [][]byte {
	var board [][]byte
	for _, item := range compact {
		board = append(board, []byte(item))
	}
	return board
}

func generic(t *testing.T, expected []string, board [][]byte) {
	for i, boardI := range board {
		if expected[i] != string(boardI) {
			t.Errorf("Solve - Expected %v, got %v!", expected[i], string(boardI))
		}
	}
}

func TestSmall(t *testing.T) {
	compact := []string{"XXXX", "XOOX", "XXOX", "XOXX"}
	board := construct(compact)
	solve(board)
	expected := []string{"XXXX", "XXXX", "XXXX", "XOXX"}
	generic(t, expected, board)
}

